bool finish_handshake() {
    if (!state_ || !handshaking_) return false;
    std::shared_ptr<State> state = state_;
    {
        std::lock_guard<std::mutex> lock(state->mutex);
        --state->handshakes;
        --state->buckets[slot_].handshakes;
        handshaking_ = false;
    }
    return true;
}

